// Signs a request to Convex: HMAC-SHA256 over `${timestamp}.${rawBody}` with
// LENDLOOP_INBOUND_SECRET (see setting() below), never stored here.
// Settings come from n8n Variables ($vars) on n8n Cloud, or from the container env
// (n8n/.env) when self-hosted. Neither is stored in this workflow.
function setting(name, fallback) {
  let value = $vars?.[name];
  if (!value) {
    try {
      value = $env[name];
    } catch {
      // n8n Cloud blocks $env; the value must then come from Variables.
    }
  }
  if (value) return value;
  if (fallback !== undefined) return fallback;
  throw new Error(`${name} is not set: add it as an n8n Variable (n8n Cloud) or in n8n/.env (self-hosted)`);
}

const crypto = require('crypto');
function signed(body) {
  const raw = body === undefined ? '' : JSON.stringify(body);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto
    .createHmac('sha256', setting('LENDLOOP_INBOUND_SECRET'))
    .update(`${timestamp}.${raw}`)
    .digest('hex');
  return { raw, timestamp, signature };
}

// Reports the failed execution to Convex. executionId makes a retried report a no-op.
// A trigger failure has no execution ID, so fall back to the trigger's timestamp.
const { execution, workflow, trigger } = $input.first().json;
const executionId = String(execution?.id ?? `trigger-${workflow?.id ?? 'unknown'}-${Date.now()}`);
const message = String(execution?.error?.message ?? trigger?.error?.message ?? 'Unknown error');
return [
  {
    json: signed({
      workflowName: workflow?.name ?? 'Unknown workflow',
      executionId,
      nodeName: execution?.lastNodeExecuted ?? undefined,
      message: message.slice(0, 1000),
    }),
  },
];
